{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Glimepiride, the closest analogue (Morgan 0.4737) sharing the arylsulfonylurea and cyclohexylurea core, has an absolute oral bioavailability of 97% in healthy volunteers, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Tolbutamide, a simpler sulfonylurea (similarity 0.3438), has an absolute oral bioavailability of 85% in humans, supporting high bioavailability for this sulfonylurea-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Paritaprevir, which contains a methylpyridine carboxamide and a sulfonylurea motif, has an absolute oral bioavailability of 52.6% in healthy volunteers, supporting high F despite a large polar structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Pafenolol, a urea-containing polar drug, has systemic availability of 46% after oral dosing, above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Levosulpiride, a polar sulfonamide-benzamide with low but above-threshold absorption, has absolute oral bioavailability of 23.4% in humans; this is the most conservative analogue and still supports F ≥20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and class-related analogues—glimepiride (97%), tolbutamide (85%), paritaprevir (52.6%), pafenolol (46%), and levosulpiride (23.4%)—all show absolute oral bioavailability at or above 20%. The strongest transferable evidence from glimepiride, which shares the sulfonylurea-cyclohexylurea scaffold, outweighs the uncertain physicochemical prior. Prediction: high.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarity to the strongest analogue glimepiride is moderate (0.4737), leaving uncertainty about the pyridine carboxamide modification.",
    "Lack of permeability, efflux, and human pharmacokinetic data for the exact query structure.",
    "Levosulpiride analogues indicate borderline absorption that could approach the 20% threshold under some conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

